        results.push({ scenario, preconditionBusy, observed, picturesLeft, uploadRequests, externalAttempts: external.length, unexpectedFetch, pageErrors, pass: observed.active && observed.focusVisible && observed.visible && picturesLeft === 0 && external.length === 0 && unexpectedFetch.length === 0 && pageErrors.length === 0 });
